public sealed record Money
{
    public decimal Amount { get; }
    public string Currency { get; }
    public Money(decimal amount, string currency)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        (Amount, Currency) = (amount, currency);
    }
    public Money Add(Money o) => o.Currency == Currency
        ? new Money(Amount + o.Amount, Currency)
        : throw new InvalidOperationException("Currency mismatch");
}

public class Order
{
    private readonly List<OrderLine> _lines = [];
    public IReadOnlyList<OrderLine> Lines => _lines;
    public void AddLine(Guid productId, int qty, Money price)
    {
        if (Status != OrderStatus.Draft) throw new DomainException("Order is closed");
        _lines.Add(new OrderLine(productId, qty, price));
    }
}

